def clean_ecg_signal(signal, fs):
    """Process a raw ECG signal and extract relevant signal features using biosppy."""
    signal = np.array(signal)

    # filter signal
    order = int(1.5 * fs)
    filtered, _, _ = st.filter_signal(
        signal=signal,
        ftype="FIR",
        band="bandpass",
        order=order,
        frequency=[0.67, 45],
        sampling_rate=fs,
    )

    filtered = filtered - np.mean(filtered)  # remove DC offset
    return filtered

def ecg_clean_beats(
    signal,
    fs,
    new_fs=None,
    filter_ecg=False,
):
    """Process a raw ECG signal and extract relevant signal features using
    default parameters. Adapted from biosppy.ecg.ecg

    Parameters
    ----------
    signal : array
        Raw ECG signal.
    fs : int, float, optional
        Sampling frequency (Hz).
    new_fs : int, float, optional
        Desired sampling frequency for output beat indices. If None, will use original fs.
    filter_ecg : bool, optional
        Whether to apply ECG filtering before beat detection. Default is False.


    Returns
    -------
    beat_indices: list of tuples
        List of (start_index, end_index) tuples for each heartbeat.
    """
    # check inputs


    if signal is None:
        raise TypeError("Please specify an input signal.")

    if new_fs is None:
        new_fs = fs

    # ensure numpy
    if filter_ecg:
        filtered = clean_ecg_signal(signal=signal, fs=fs)
    else:
        filtered = signal
    
    rpeaks = detect_heartbeats(filtered, fs)
    # correct R-peak locations
    (rpeaks,) = correct_rpeaks(
        signal=filtered, rpeaks=rpeaks, sampling_rate=fs, tol=0.05
    )
    # extract templates
    before, after = 0.2, 0.4
    before = int(before * fs)
    after = int(after * fs)
    beat_indices = extract_heartbeats(
        signal=filtered,
        rpeaks=rpeaks,
        before=before,
        after=after
    )
    if fs != new_fs:
        # rescale beat indices to new fs
        beat_indices = [
            int(idx * new_fs / fs)
            for idx in beat_indices
        ]
    return filtered, beat_indices

def extract_heartbeats(signal, rpeaks, before=200, after=400):
    """Extract heartbeat indices. Adapted from biosppy

    Parameters
    ----------
    signal : array
        Input ECG signal.
    rpeaks : array
        R-peak location indices.
    before : int, optional
        Number of samples to include before the R peak.
    after : int, optional
        Number of samples to include after the R peak.

    Returns
    -------
    beat_indices: list of tuples
        List of (start_index, end_index) tuples for each heartbeat.

    """
    R = np.sort(rpeaks)
    length = len(signal)
    beat_indices = []

    for r in R:
        a = r - before
        if a < 0:
            continue
        b = r + after
        if b > length:
            break
        beat_indices.extend([a, b])

    return beat_indices

def check_ecg_signal_quality(ecg_signal, fs, filter_ecg=True):
    try:
        ecg_length = len(ecg_signal) / fs  # in seconds
        _, beat_indices = ecg_clean_beats(ecg_signal, fs=fs, filter_ecg=filter_ecg)
        n_beats = len(beat_indices) / 2
        bpm = n_beats / (ecg_length / 60)
        if bpm < 20 or bpm > 250 or n_beats < ((ecg_length / 60) * 20) or n_beats > ((ecg_length / 60) * 250):
            return False
        else:
            return True
    except Exception as e:
        print(f"ECG quality check failed: {e}")
        return False

# %% ../nbs/03_signal.ipynb #73baa179
def create_patch_b2b(xb, beat_indices, resample_length=256, fill_missing_beats=False):
    """
    xb: [n_vars x seq_len]
    out: [num_patch x n_vars x patch_len]
    """
    missing_beat_indices = []
    if len(beat_indices) == 0:
        raise ValueError("No beats detected in ECG signal for beat-to-beat patching. Check samples.")
    prev_end = beat_indices[0]
    for i, (s, e) in enumerate(zip(beat_indices[::2], beat_indices[1::2])):
        if s - prev_end >= (e - s) * 0.95:
            missing_beat_indices.append(i)
        prev_end = e

    first_beat_start_idx = beat_indices[0]
    last_beat_end_idx = beat_indices[-1]

    xb_patched = list(np.array_split(xb, beat_indices, axis=-1)[1:-2:2])  # skip first, last, grab every other (how tensor split works)
    # here is where you could add zero value patches!
    if fill_missing_beats:
        for idx in missing_beat_indices:
            xb_patched.insert(idx, np.zeros_like(xb_patched[0]))
        n_beats_beginning = (first_beat_start_idx - 0) / xb_patched[0].shape[-1]
        n_beats_end = (xb.shape[-1] - last_beat_end_idx) / xb_patched[0].shape[-1]
        for _ in range(int(n_beats_beginning)):
            xb_patched.insert(0, np.zeros_like(xb_patched[0]))
        for _ in range(int(n_beats_end)):
            xb_patched.append(np.zeros_like(xb_patched[0]))
    
    xb_stacked = np.stack(xb_patched, axis=0)
    xb_resampled = signal.resample(xb_stacked, resample_length, axis=-1)
    return xb_resampled
